import{_ as i,o as a,c as e,aO as t}from"./chunks/framework.vjUPZZJn.js";const c=JSON.parse('{"title":"C 语言 sizeof 与 strlen：编译期大小与运行时长度","description":"","frontmatter":{"date":"2026-11-09T21:30:00.000Z","title":"C 语言 sizeof 与 strlen：编译期大小与运行时长度","source":"[[1-知识/C++/C语言中的 sizeof 和 strlen()]]","tags":["编程语言","学习笔记","C"],"categories":["计算机"],"permalink":"/pages/ae5cd4"},"headers":[],"relativePath":"计算机/C 语言 sizeof 与 strlen：编译期大小与运行时长度.md","filePath":"计算机/C 语言 sizeof 与 strlen：编译期大小与运行时长度.md","lastUpdated":1794223026000}'),n={name:"计算机/C 语言 sizeof 与 strlen：编译期大小与运行时长度.md"};function l(o,s,h,p,d,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="c-语言-sizeof-与-strlen-编译期大小与运行时长度" tabindex="-1">C 语言 sizeof 与 strlen：编译期大小与运行时长度 <a class="header-anchor" href="#c-语言-sizeof-与-strlen-编译期大小与运行时长度" aria-label="Permalink to &quot;C 语言 sizeof 与 strlen：编译期大小与运行时长度&quot;">​</a></h1> <p>sizeof 和 strlen 都在与&quot;长度&quot;打交道，初学 C 时很容易混用：拿 sizeof 去算字符串长度、或拿 strlen 去算缓冲区大小，都埋过不少雷。两者的差别不在&quot;量什么&quot;，而在&quot;什么时候量&quot;——sizeof 是编译期由类型确定的运算符，strlen 是运行期逐字符扫描的库函数。本文从这个时机差异出发，讲清两者的行为边界与三个常见陷阱，适合刚开始写 C、或想复核基础概念的读者。</p> <h2 id="一个是运算符-一个是库函数" tabindex="-1">一个是运算符，一个是库函数 <a class="header-anchor" href="#一个是运算符-一个是库函数" aria-label="Permalink to &quot;一个是运算符，一个是库函数&quot;">​</a></h2> <p>sizeof 是 C 语言的关键字级<strong>运算符</strong>，以字节为单位给出操作数的大小，不需要包含任何头文件（返回类型 <code>size_t</code> 的定义在 <code>&lt;stddef.h&gt;</code>，不过 <code>&lt;stdio.h&gt;</code>、<code>&lt;string.h&gt;</code> 等常用头文件里也有）。它在编译期就由类型确定结果，生成的机器码里往往只剩一个常量。</p> <p>strlen() 是 <code>&lt;string.h&gt;</code> 提供的<strong>库函数</strong>，从给定地址开始逐字符扫描，直到遇到结尾的 <code>&#39;\\0&#39;</code> 才停，返回的字符数不含这个终止符。扫描发生在运行期，代价与字符串实际长度成正比，也依赖字符串正确终止——没有 <code>&#39;\\0&#39;</code> 它会一路读越界。</p> <p>一句话区分：sizeof 量的是&quot;这块内存有多大&quot;，strlen 量的是&quot;这段内容有多长&quot;。</p> <h2 id="同一个-hello-两组不同的答案" tabindex="-1">同一个 &quot;hello&quot;，两组不同的答案 <a class="header-anchor" href="#同一个-hello-两组不同的答案" aria-label="Permalink to &quot;同一个 &quot;hello&quot;，两组不同的答案&quot;">​</a></h2> <p>用数组定义和用指针定义同一个字符串字面量，sizeof 给出的结果完全不同：</p> <div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">[]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 数组：6 个字节（5 个字符 + &#39;\\0&#39;）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p   </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 指针：变量里存的是字符串首地址</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%zu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> %zu\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(a), </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">strlen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(a));</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 6 5</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%zu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> %zu\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(p), </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">strlen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(p));</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 8 5（64 位系统上指针 8 字节）</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>四个结果的由来：</p> <ul><li><code>sizeof(a)</code> 是整个数组的字节数，包含 <code>&#39;\\0&#39;</code>；</li> <li><code>strlen(a)</code> 数到 <code>&#39;\\0&#39;</code> 为止，不包含它；</li> <li><code>sizeof(p)</code> 只是指针变量本身的大小，与它指向的字符串无关；</li> <li><code>strlen(p)</code> 沿地址扫描到 <code>&#39;\\0&#39;</code>，结果与 <code>strlen(a)</code> 一致。</li></ul> <p>这组对照也解释了为什么&quot;用 sizeof 算字符串长度&quot;总是差一（多算了 <code>&#39;\\0&#39;</code>），而&quot;用 strlen 算缓冲区大小&quot;则是类型层面的误解——它根本不反映内存块的大小。</p> <h2 id="数组传进函数就退化为指针" tabindex="-1">数组传进函数就退化为指针 <a class="header-anchor" href="#数组传进函数就退化为指针" aria-label="Permalink to &quot;数组传进函数就退化为指针&quot;">​</a></h2> <p>数组一旦出现在函数形参列表里，实际类型就是指针：<code>int f(int a[2])</code> 与 <code>int f(int* a)</code> 声明的是同一个函数。因此函数内部对形参做 sizeof，得到的是指针大小，而不是调用方数组的大小：</p> <div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%zu\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(a));</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 8（64 位下的指针大小），不是 40</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>数组长度信息在传参边界上丢失了，需要长度就得作为独立参数传入。值得一提的是，sizeof 作用于数组本身正是数组&quot;不退化&quot;为指针的少数场景之一（另一个常见的例外是取地址 <code>&amp;</code>），所以这个坑只出现在函数调用边界上，同一作用域内 <code>sizeof(a)</code> 仍然是完整数组的大小。</p> <h2 id="sizeof-不求值它的操作数" tabindex="-1">sizeof 不求值它的操作数 <a class="header-anchor" href="#sizeof-不求值它的操作数" aria-label="Permalink to &quot;sizeof 不求值它的操作数&quot;">​</a></h2> <p>sizeof 的操作数是表达式时，表达式本身并不求值——<code>sizeof(i++)</code> 不会让 <code>i</code> 自增，编译器只根据表达式类型得出大小，结果还可以用在整型常量表达式里。这既有用（可以写 <code>sizeof(x)/sizeof(x[0])</code> 这类数组长度惯用法，无副作用），也容易让人误判：调试时指望 sizeof &quot;顺带&quot;改个值是不可能的。</p> <p>例外是 C99 的变长数组（VLA）：数组长度要到运行期才知道，此时 sizeof 的操作数会被求值，结果也不再是编译期常量。</p> <h2 id="打印结果用-zu" tabindex="-1">打印结果用 %zu <a class="header-anchor" href="#打印结果用-zu" aria-label="Permalink to &quot;打印结果用 %zu&quot;">​</a></h2> <p>sizeof 和 strlen 的返回类型都是无符号的 <code>size_t</code>。C99 引入了 <code>z</code> 长度修饰符来配合它：无符号对应 <code>%zu</code>，有符号版本（如 <code>ptrdiff_t</code> 一类）对应 <code>%zd</code>。打印两者的返回值用 <code>%zu</code> 最准确；用 <code>%d</code> 接 <code>size_t</code> 属于类型不匹配，行为未定义，64 位平台上常见的乱码输出就来自这类错配。格式串各成分的完整说明可以参考 <a href="./printf 转换说明与修饰符速查.html">printf 转换说明与修饰符速查</a>。</p> <h2 id="圆括号什么时候必须" tabindex="-1">圆括号什么时候必须 <a class="header-anchor" href="#圆括号什么时候必须" aria-label="Permalink to &quot;圆括号什么时候必须&quot;">​</a></h2> <p>sizeof 的圆括号规则取决于操作数是类型还是表达式：</p> <ol><li>操作数是类型时，圆括号必不可少：<code>sizeof(int)</code>；</li> <li>操作数是具体的量时，圆括号可有可无：<code>sizeof name</code>、<code>sizeof 6.28</code> 都合法。</li></ol> <p>尽管如此，建议所有情况都带上圆括号——与 <code>sizeof name</code> 相比，<code>sizeof(name)</code> 没有任何代价，还能避免在类型与表达式混用的场景里出错。</p> <h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2> <ul><li>sizeof 是运算符，编译期由类型得出字节数；strlen 是库函数，运行期扫描到 <code>&#39;\\0&#39;</code> 得出字符数；</li> <li>数组与指针：sizeof 对数组是整块大小（含 <code>&#39;\\0&#39;</code>），对指针是指针自身大小；strlen 两者一致；</li> <li>数组作函数参数退化为指针，函数内的 sizeof 拿不到原数组大小，长度要单独传；</li> <li>sizeof 不求值操作数（VLA 除外）；</li> <li>打印 size_t 用 <code>%zu</code>；类型与转换说明不匹配是未定义行为。</li></ul>`,51)])])}const u=i(n,[["render",l]]);export{c as __pageData,u as default};
